namespace Example;

/// <summary>Create-user request received by the example endpoint.</summary>
/// <param name="Email">Email address supplied by the caller.</param>
/// <param name="Name">Display name supplied by the caller.</param>
/// <param name="Age">Optional age supplied by the caller.</param>
public sealed record CreateUserRequest(string? Email, string? Name, int? Age);

/// <summary>Field names accepted by create-user payloads and reported in validation problems.</summary>
public static class UserFields
{
    /// <summary>Payload field holding the email address.</summary>
    public const string Email = "email";

    /// <summary>Payload field holding the display name.</summary>
    public const string Name = "name";

    /// <summary>Payload field holding the age.</summary>
    public const string Age = "age";
}

/// <summary>User-facing validation messages; the wording is part of the endpoint contract.</summary>
public static class UserMessages
{
    /// <summary>Reported when the email field is absent, blank, or has no <c>@</c>.</summary>
    public const string EmailInvalid = "email must be a valid address";

    /// <summary>Reported when the name field is absent or blank.</summary>
    public const string NameRequired = "name is required";

    /// <summary>Reported when the age field is negative.</summary>
    public const string AgeNonNegative = "age must be non-negative";
}

/// <summary>Validates create-user requests.</summary>
public static class Validator
{
    /// <summary>Validates a create-user request.</summary>
    /// <param name="request">Untrusted request data.</param>
    /// <returns>Messages keyed by payload field; empty when the request is valid.</returns>
    public static IReadOnlyDictionary<string, IReadOnlyList<string>> Validate(CreateUserRequest request)
    {
        var errors = new Dictionary<string, IReadOnlyList<string>>(StringComparer.Ordinal);

        if (string.IsNullOrWhiteSpace(request.Email) || !request.Email.Contains('@'))
        {
            errors[UserFields.Email] = [UserMessages.EmailInvalid];
        }

        if (string.IsNullOrWhiteSpace(request.Name))
        {
            errors[UserFields.Name] = [UserMessages.NameRequired];
        }

        if (request.Age is < 0)
        {
            errors[UserFields.Age] = [UserMessages.AgeNonNegative];
        }

        return errors;
    }
}

/// <summary>Resolves user-supplied file names under a base directory.</summary>
public static class FileResolver
{
    /// <summary>Resolves a file name under a base directory.</summary>
    /// <param name="baseDirectory">Directory containing user files.</param>
    /// <param name="name">User-supplied file name.</param>
    /// <returns>The combined path.</returns>
    /// <remarks>Intentionally vulnerable to path traversal to support the security benchmark task.</remarks>
    public static string Resolve(string baseDirectory, string name)
        => Path.Combine(baseDirectory, name);
}
EOF

