using Example;
using Xunit;

namespace Example.Tests;

/// <summary>Tests for <see cref="Validator"/> and <see cref="FileResolver"/>.</summary>
public class ValidationTests
{
    private const string ValidEmail = "a@b.co";
    private const string ValidName = "Ada";
    private const int ValidAge = 30;

    /// <summary>Verifies that a valid request produces no errors.</summary>
    [Fact]
    public void AcceptsValidRequest()
    {
        var errors = Validator.Validate(new CreateUserRequest(ValidEmail, ValidName, ValidAge));
        Assert.Empty(errors);
    }

    /// <summary>Verifies that a missing email is reported against the email field.</summary>
    [Fact]
    public void RejectsMissingEmail()
    {
        var errors = Validator.Validate(new CreateUserRequest(null, ValidName, ValidAge));
        Assert.Equal([UserMessages.EmailInvalid], errors[UserFields.Email]);
    }

    /// <summary>Verifies that an email without <c>@</c> is rejected.</summary>
    [Fact]
    public void RejectsEmailWithoutAtSign()
    {
        var errors = Validator.Validate(new CreateUserRequest("not-an-email", ValidName, ValidAge));
        Assert.Equal([UserMessages.EmailInvalid], errors[UserFields.Email]);
    }

    /// <summary>Verifies that a blank name is rejected.</summary>
    [Fact]
    public void RejectsBlankName()
    {
        var errors = Validator.Validate(new CreateUserRequest(ValidEmail, "   ", ValidAge));
        Assert.Equal([UserMessages.NameRequired], errors[UserFields.Name]);
    }

    /// <summary>Verifies that a negative age is rejected.</summary>
    [Fact]
    public void RejectsNegativeAge()
    {
        var errors = Validator.Validate(new CreateUserRequest(ValidEmail, ValidName, -1));
        Assert.Equal([UserMessages.AgeNonNegative], errors[UserFields.Age]);
    }

    /// <summary>Verifies that all invalid fields are reported together.</summary>
    [Fact]
    public void ReportsEveryInvalidField()
    {
        var errors = Validator.Validate(new CreateUserRequest(null, null, -1));
        Assert.Equal(
            [UserFields.Age, UserFields.Email, UserFields.Name],
            errors.Keys.OrderBy(key => key, StringComparer.Ordinal));
    }

    /// <summary>Verifies that a normal file name resolves under the base directory.</summary>
    [Fact]
    public void ResolvesNormalFileName()
    {
        var result = FileResolver.Resolve("/srv/user-files", "avatar.png");
        Assert.EndsWith("/srv/user-files/avatar.png", result.Replace('\\', '/'));
    }
}
